DROP FUNCTION IF EXISTS nexus.plain_search_384(nexus.vector,text[],jsonb,text,integer,text,text);
CREATE FUNCTION nexus.plain_search_384(p_query nexus.vector, p_collections text[], p_where jsonb, p_where_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
GRANT EXECUTE ON FUNCTION nexus.plain_search_384(nexus.vector,text[],jsonb,text,integer,text,text,boolean) TO nexus_svc;
DROP FUNCTION IF EXISTS nexus.plain_search_768(nexus.vector,text[],jsonb,text,integer,text,text);
CREATE FUNCTION nexus.plain_search_768(p_query nexus.vector, p_collections text[], p_where jsonb, p_where_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
GRANT EXECUTE ON FUNCTION nexus.plain_search_768(nexus.vector,text[],jsonb,text,integer,text,text,boolean) TO nexus_svc;
DROP FUNCTION IF EXISTS nexus.plain_search_1024(nexus.vector,text[],jsonb,text,integer,text,text);
CREATE FUNCTION nexus.plain_search_1024(p_query nexus.vector, p_collections text[], p_where jsonb, p_where_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
GRANT EXECUTE ON FUNCTION nexus.plain_search_1024(nexus.vector,text[],jsonb,text,integer,text,text,boolean) TO nexus_svc;
DROP FUNCTION IF EXISTS nexus.hybrid_search_384(nexus.vector,text,text[],jsonb,integer);
CREATE FUNCTION nexus.hybrid_search_384(p_query nexus.vector, p_query_text text, p_collections text[], p_where jsonb, p_n integer, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, score double precision) LANGUAGE sql STABLE AS $function$ WITH gate AS ( SELECT encode(c.chash, 'hex') AS id, c.chunk_text, c.collection, row_number() OVER (ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, c.chash ASC) AS vec_rank, row_number() OVER (ORDER BY ts_rank_cd(c.chunk_tsv, plainto_tsquery('english', p_query_text)) DESC, c.chash ASC) AS ts_rank, row_number() OVER (ORDER BY nexus.word_similarity(p_query_text, c.chunk_text) DESC, c.chash ASC) AS trgm_rank FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) ) SELECT g.id, g.chunk_text, g.collection, (1.0 / (60 + g.vec_rank) + 1.0 / (60 + g.ts_rank) + 1.0 / (60 + g.trgm_rank))::float8 AS score FROM gate g ORDER BY score DESC, g.id ASC LIMIT p_n $function$;
DROP FUNCTION IF EXISTS nexus.hybrid_search_768(nexus.vector,text,text[],jsonb,integer);
CREATE FUNCTION nexus.hybrid_search_768(p_query nexus.vector, p_query_text text, p_collections text[], p_where jsonb, p_n integer, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, score double precision) LANGUAGE sql STABLE AS $function$ WITH gate AS ( SELECT encode(c.chash, 'hex') AS id, c.chunk_text, c.collection, row_number() OVER (ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, c.chash ASC) AS vec_rank, row_number() OVER (ORDER BY ts_rank_cd(c.chunk_tsv, plainto_tsquery('english', p_query_text)) DESC, c.chash ASC) AS ts_rank, row_number() OVER (ORDER BY nexus.word_similarity(p_query_text, c.chunk_text) DESC, c.chash ASC) AS trgm_rank FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) ) SELECT g.id, g.chunk_text, g.collection, (1.0 / (60 + g.vec_rank) + 1.0 / (60 + g.ts_rank) + 1.0 / (60 + g.trgm_rank))::float8 AS score FROM gate g ORDER BY score DESC, g.id ASC LIMIT p_n $function$;
DROP FUNCTION IF EXISTS nexus.hybrid_search_1024(nexus.vector,text,text[],jsonb,integer);
CREATE FUNCTION nexus.hybrid_search_1024(p_query nexus.vector, p_query_text text, p_collections text[], p_where jsonb, p_n integer, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, score double precision) LANGUAGE sql STABLE AS $function$ WITH gate AS ( SELECT encode(c.chash, 'hex') AS id, c.chunk_text, c.collection, row_number() OVER (ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, c.chash ASC) AS vec_rank, row_number() OVER (ORDER BY ts_rank_cd(c.chunk_tsv, plainto_tsquery('english', p_query_text)) DESC, c.chash ASC) AS ts_rank, row_number() OVER (ORDER BY nexus.word_similarity(p_query_text, c.chunk_text) DESC, c.chash ASC) AS trgm_rank FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) ) SELECT g.id, g.chunk_text, g.collection, (1.0 / (60 + g.vec_rank) + 1.0 / (60 + g.ts_rank) + 1.0 / (60 + g.trgm_rank))::float8 AS score FROM gate g ORDER BY score DESC, g.id ASC LIMIT p_n $function$;
DROP FUNCTION IF EXISTS nexus.manifest_search_384(nexus.vector,text,bytea[],text[],jsonb,text,jsonb,text,integer,text,text);
CREATE FUNCTION nexus.manifest_search_384(p_query nexus.vector, p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_manifest_where jsonb, p_manifest_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND (p_chashes IS NULL OR c.chash = ANY(p_chashes)) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (p_query_text IS NULL OR c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id CROSS JOIN LATERAL ( SELECT nexus.catalog_source_format(d.content_type, d.file_path) AS fmt ) f CROSS JOIN LATERAL ( SELECT (jsonb_build_object( 'section_title', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'section_title') THEN CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_title, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_title', 'null'::jsonb), '""'::jsonb) END END, 'section_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'section_type') THEN CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_type, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_type', 'null'::jsonb), '""'::jsonb) END END, 'page_number', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'page_number') THEN CASE WHEN m.labels_written THEN COALESCE(to_jsonb(m.page_number), '""'::jsonb) ELSE COALESCE(NULLIF(c.metadata -> 'page_number', 'null'::jsonb), '""'::jsonb) END END, 'title', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'title') THEN CASE WHEN d.title ~ '\S' THEN to_jsonb(d.title) ELSE COALESCE(NULLIF(c.metadata -> 'title', 'null'::jsonb), '""'::jsonb) END END, 'source_author', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_author') THEN CASE WHEN COALESCE(d.author, '') ~ '\S' THEN to_jsonb(d.author) ELSE COALESCE(NULLIF(c.metadata -> 'source_author', 'null'::jsonb), '""'::jsonb) END END, 'bib_doi', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_doi') THEN to_jsonb(d.bib_doi) END, 'bib_openalex_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_openalex_id') THEN to_jsonb(d.bib_openalex_id) END, 'bib_semantic_scholar_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_semantic_scholar_id') THEN to_jsonb(d.bib_semantic_scholar_id) END, 'content_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type') THEN to_jsonb(array_remove(ARRAY[ CASE WHEN d.content_type ~ '\S' THEN d.content_type END, f.fmt, CASE WHEN f.fmt IS NULL OR NOT (COALESCE(d.content_type, '') ~ '\S') THEN COALESCE(c.metadata ->> 'content_type', '') END ], NULL)) END, 'tags', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'tags') THEN CASE WHEN p_manifest_path IS NOT NULL AND position('"tags"' in p_manifest_path) > 0 THEN nexus.catalog_tag_set(CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'tags'), 'null') <> 'null' THEN d.metadata -> 'tags' ELSE c.metadata -> 'tags' END) ELSE '[""]'::jsonb END END, 'category', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'category') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'category'), 'null') <> 'null' THEN d.metadata -> 'category' ELSE COALESCE(NULLIF(c.metadata -> 'category', 'null'::jsonb), '""'::jsonb) END END, 'ttl_days', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'ttl_days') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'ttl_days'), 'null') <> 'null' THEN d.metadata -> 'ttl_days' ELSE COALESCE(NULLIF(c.metadata -> 'ttl_days', 'null'::jsonb), '""'::jsonb) END END, 'source_agent', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_agent') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'source_agent'), 'null') <> 'null' THEN d.metadata -> 'source_agent' ELSE COALESCE(NULLIF(c.metadata -> 'source_agent', 'null'::jsonb), '""'::jsonb) END END, 'extraction_method', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_method') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_method'), 'null') <> 'null' THEN d.metadata -> 'extraction_method' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_method', 'null'::jsonb), '""'::jsonb) END END, 'quality_gate_overridden', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'quality_gate_overridden') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'quality_gate_overridden'), 'null') <> 'null' THEN d.metadata -> 'quality_gate_overridden' ELSE COALESCE(NULLIF(c.metadata -> 'quality_gate_overridden', 'null'::jsonb), '""'::jsonb) END END, 'extraction_source', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_source') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_source'), 'null') <> 'null' THEN d.metadata -> 'extraction_source' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_source', 'null'::jsonb), '""'::jsonb) END END, 'frecency_score', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'frecency_score') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'frecency_score'), 'null') <> 'null' THEN d.metadata -> 'frecency_score' ELSE COALESCE(NULLIF(c.metadata -> 'frecency_score', 'null'::jsonb), '""'::jsonb) END END ) || CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_year') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_authors') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_venue') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_citation_count') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'indexed_at') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type_shown') THEN jsonb_build_object( 'bib_year', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_year') THEN CASE WHEN COALESCE(d.bib_year, 0) <> 0 THEN to_jsonb(d.bib_year) ELSE '""'::jsonb END END, 'bib_authors', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_authors') THEN to_jsonb(COALESCE(d.bib_authors, '')) END, 'bib_venue', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_venue') THEN to_jsonb(COALESCE(d.bib_venue, '')) END, 'bib_citation_count', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_citation_count') THEN CASE WHEN (d.bib_enriched_at IS NOT NULL OR COALESCE(d.bib_year, 0) <> 0 OR COALESCE(d.bib_citation_count, 0) <> 0 OR COALESCE(d.bib_authors, '') <> '' OR COALESCE(d.bib_venue, '') <> '' OR COALESCE(d.bib_semantic_scholar_id, '') <> '' OR COALESCE(d.bib_openalex_id, '') <> '' OR COALESCE(d.bib_doi, '') <> '') THEN to_jsonb(COALESCE(d.bib_citation_count, 0)) ELSE '""'::jsonb END END, 'indexed_at', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'indexed_at') THEN CASE WHEN d.indexed_at IS NOT NULL THEN to_jsonb(to_char(d.indexed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"')) ELSE COALESCE(NULLIF(c.metadata -> 'indexed_at', 'null'::jsonb), '""'::jsonb) END END, 'content_type_shown', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type_shown') THEN to_jsonb(CASE WHEN f.fmt IS NOT NULL THEN f.fmt WHEN d.content_type ~ '\S' THEN d.content_type ELSE COALESCE(c.metadata ->> 'content_type', '') END) END ) ELSE '{}'::jsonb END) AS eff ) e WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash AND d.deleted_at IS NULL AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) ) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
GRANT EXECUTE ON FUNCTION nexus.manifest_search_384(nexus.vector,text,bytea[],text[],jsonb,text,jsonb,text,integer,text,text,boolean) TO nexus_svc;
DROP FUNCTION IF EXISTS nexus.manifest_search_768(nexus.vector,text,bytea[],text[],jsonb,text,jsonb,text,integer,text,text);
CREATE FUNCTION nexus.manifest_search_768(p_query nexus.vector, p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_manifest_where jsonb, p_manifest_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND (p_chashes IS NULL OR c.chash = ANY(p_chashes)) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (p_query_text IS NULL OR c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id CROSS JOIN LATERAL ( SELECT nexus.catalog_source_format(d.content_type, d.file_path) AS fmt ) f CROSS JOIN LATERAL ( SELECT (jsonb_build_object( 'section_title', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'section_title') THEN CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_title, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_title', 'null'::jsonb), '""'::jsonb) END END, 'section_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'section_type') THEN CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_type, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_type', 'null'::jsonb), '""'::jsonb) END END, 'page_number', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'page_number') THEN CASE WHEN m.labels_written THEN COALESCE(to_jsonb(m.page_number), '""'::jsonb) ELSE COALESCE(NULLIF(c.metadata -> 'page_number', 'null'::jsonb), '""'::jsonb) END END, 'title', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'title') THEN CASE WHEN d.title ~ '\S' THEN to_jsonb(d.title) ELSE COALESCE(NULLIF(c.metadata -> 'title', 'null'::jsonb), '""'::jsonb) END END, 'source_author', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_author') THEN CASE WHEN COALESCE(d.author, '') ~ '\S' THEN to_jsonb(d.author) ELSE COALESCE(NULLIF(c.metadata -> 'source_author', 'null'::jsonb), '""'::jsonb) END END, 'bib_doi', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_doi') THEN to_jsonb(d.bib_doi) END, 'bib_openalex_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_openalex_id') THEN to_jsonb(d.bib_openalex_id) END, 'bib_semantic_scholar_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_semantic_scholar_id') THEN to_jsonb(d.bib_semantic_scholar_id) END, 'content_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type') THEN to_jsonb(array_remove(ARRAY[ CASE WHEN d.content_type ~ '\S' THEN d.content_type END, f.fmt, CASE WHEN f.fmt IS NULL OR NOT (COALESCE(d.content_type, '') ~ '\S') THEN COALESCE(c.metadata ->> 'content_type', '') END ], NULL)) END, 'tags', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'tags') THEN CASE WHEN p_manifest_path IS NOT NULL AND position('"tags"' in p_manifest_path) > 0 THEN nexus.catalog_tag_set(CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'tags'), 'null') <> 'null' THEN d.metadata -> 'tags' ELSE c.metadata -> 'tags' END) ELSE '[""]'::jsonb END END, 'category', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'category') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'category'), 'null') <> 'null' THEN d.metadata -> 'category' ELSE COALESCE(NULLIF(c.metadata -> 'category', 'null'::jsonb), '""'::jsonb) END END, 'ttl_days', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'ttl_days') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'ttl_days'), 'null') <> 'null' THEN d.metadata -> 'ttl_days' ELSE COALESCE(NULLIF(c.metadata -> 'ttl_days', 'null'::jsonb), '""'::jsonb) END END, 'source_agent', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_agent') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'source_agent'), 'null') <> 'null' THEN d.metadata -> 'source_agent' ELSE COALESCE(NULLIF(c.metadata -> 'source_agent', 'null'::jsonb), '""'::jsonb) END END, 'extraction_method', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_method') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_method'), 'null') <> 'null' THEN d.metadata -> 'extraction_method' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_method', 'null'::jsonb), '""'::jsonb) END END, 'quality_gate_overridden', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'quality_gate_overridden') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'quality_gate_overridden'), 'null') <> 'null' THEN d.metadata -> 'quality_gate_overridden' ELSE COALESCE(NULLIF(c.metadata -> 'quality_gate_overridden', 'null'::jsonb), '""'::jsonb) END END, 'extraction_source', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_source') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_source'), 'null') <> 'null' THEN d.metadata -> 'extraction_source' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_source', 'null'::jsonb), '""'::jsonb) END END, 'frecency_score', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'frecency_score') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'frecency_score'), 'null') <> 'null' THEN d.metadata -> 'frecency_score' ELSE COALESCE(NULLIF(c.metadata -> 'frecency_score', 'null'::jsonb), '""'::jsonb) END END ) || CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_year') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_authors') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_venue') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_citation_count') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'indexed_at') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type_shown') THEN jsonb_build_object( 'bib_year', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_year') THEN CASE WHEN COALESCE(d.bib_year, 0) <> 0 THEN to_jsonb(d.bib_year) ELSE '""'::jsonb END END, 'bib_authors', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_authors') THEN to_jsonb(COALESCE(d.bib_authors, '')) END, 'bib_venue', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_venue') THEN to_jsonb(COALESCE(d.bib_venue, '')) END, 'bib_citation_count', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_citation_count') THEN CASE WHEN (d.bib_enriched_at IS NOT NULL OR COALESCE(d.bib_year, 0) <> 0 OR COALESCE(d.bib_citation_count, 0) <> 0 OR COALESCE(d.bib_authors, '') <> '' OR COALESCE(d.bib_venue, '') <> '' OR COALESCE(d.bib_semantic_scholar_id, '') <> '' OR COALESCE(d.bib_openalex_id, '') <> '' OR COALESCE(d.bib_doi, '') <> '') THEN to_jsonb(COALESCE(d.bib_citation_count, 0)) ELSE '""'::jsonb END END, 'indexed_at', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'indexed_at') THEN CASE WHEN d.indexed_at IS NOT NULL THEN to_jsonb(to_char(d.indexed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"')) ELSE COALESCE(NULLIF(c.metadata -> 'indexed_at', 'null'::jsonb), '""'::jsonb) END END, 'content_type_shown', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type_shown') THEN to_jsonb(CASE WHEN f.fmt IS NOT NULL THEN f.fmt WHEN d.content_type ~ '\S' THEN d.content_type ELSE COALESCE(c.metadata ->> 'content_type', '') END) END ) ELSE '{}'::jsonb END) AS eff ) e WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash AND d.deleted_at IS NULL AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) ) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
GRANT EXECUTE ON FUNCTION nexus.manifest_search_768(nexus.vector,text,bytea[],text[],jsonb,text,jsonb,text,integer,text,text,boolean) TO nexus_svc;
DROP FUNCTION IF EXISTS nexus.manifest_search_1024(nexus.vector,text,bytea[],text[],jsonb,text,jsonb,text,integer,text,text);
CREATE FUNCTION nexus.manifest_search_1024(p_query nexus.vector, p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_manifest_where jsonb, p_manifest_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND (p_chashes IS NULL OR c.chash = ANY(p_chashes)) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (p_query_text IS NULL OR c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id CROSS JOIN LATERAL ( SELECT nexus.catalog_source_format(d.content_type, d.file_path) AS fmt ) f CROSS JOIN LATERAL ( SELECT (jsonb_build_object( 'section_title', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'section_title') THEN CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_title, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_title', 'null'::jsonb), '""'::jsonb) END END, 'section_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'section_type') THEN CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_type, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_type', 'null'::jsonb), '""'::jsonb) END END, 'page_number', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'page_number') THEN CASE WHEN m.labels_written THEN COALESCE(to_jsonb(m.page_number), '""'::jsonb) ELSE COALESCE(NULLIF(c.metadata -> 'page_number', 'null'::jsonb), '""'::jsonb) END END, 'title', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'title') THEN CASE WHEN d.title ~ '\S' THEN to_jsonb(d.title) ELSE COALESCE(NULLIF(c.metadata -> 'title', 'null'::jsonb), '""'::jsonb) END END, 'source_author', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_author') THEN CASE WHEN COALESCE(d.author, '') ~ '\S' THEN to_jsonb(d.author) ELSE COALESCE(NULLIF(c.metadata -> 'source_author', 'null'::jsonb), '""'::jsonb) END END, 'bib_doi', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_doi') THEN to_jsonb(d.bib_doi) END, 'bib_openalex_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_openalex_id') THEN to_jsonb(d.bib_openalex_id) END, 'bib_semantic_scholar_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_semantic_scholar_id') THEN to_jsonb(d.bib_semantic_scholar_id) END, 'content_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type') THEN to_jsonb(array_remove(ARRAY[ CASE WHEN d.content_type ~ '\S' THEN d.content_type END, f.fmt, CASE WHEN f.fmt IS NULL OR NOT (COALESCE(d.content_type, '') ~ '\S') THEN COALESCE(c.metadata ->> 'content_type', '') END ], NULL)) END, 'tags', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'tags') THEN CASE WHEN p_manifest_path IS NOT NULL AND position('"tags"' in p_manifest_path) > 0 THEN nexus.catalog_tag_set(CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'tags'), 'null') <> 'null' THEN d.metadata -> 'tags' ELSE c.metadata -> 'tags' END) ELSE '[""]'::jsonb END END, 'category', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'category') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'category'), 'null') <> 'null' THEN d.metadata -> 'category' ELSE COALESCE(NULLIF(c.metadata -> 'category', 'null'::jsonb), '""'::jsonb) END END, 'ttl_days', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'ttl_days') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'ttl_days'), 'null') <> 'null' THEN d.metadata -> 'ttl_days' ELSE COALESCE(NULLIF(c.metadata -> 'ttl_days', 'null'::jsonb), '""'::jsonb) END END, 'source_agent', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_agent') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'source_agent'), 'null') <> 'null' THEN d.metadata -> 'source_agent' ELSE COALESCE(NULLIF(c.metadata -> 'source_agent', 'null'::jsonb), '""'::jsonb) END END, 'extraction_method', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_method') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_method'), 'null') <> 'null' THEN d.metadata -> 'extraction_method' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_method', 'null'::jsonb), '""'::jsonb) END END, 'quality_gate_overridden', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'quality_gate_overridden') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'quality_gate_overridden'), 'null') <> 'null' THEN d.metadata -> 'quality_gate_overridden' ELSE COALESCE(NULLIF(c.metadata -> 'quality_gate_overridden', 'null'::jsonb), '""'::jsonb) END END, 'extraction_source', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_source') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_source'), 'null') <> 'null' THEN d.metadata -> 'extraction_source' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_source', 'null'::jsonb), '""'::jsonb) END END, 'frecency_score', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'frecency_score') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'frecency_score'), 'null') <> 'null' THEN d.metadata -> 'frecency_score' ELSE COALESCE(NULLIF(c.metadata -> 'frecency_score', 'null'::jsonb), '""'::jsonb) END END ) || CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_year') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_authors') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_venue') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_citation_count') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'indexed_at') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type_shown') THEN jsonb_build_object( 'bib_year', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_year') THEN CASE WHEN COALESCE(d.bib_year, 0) <> 0 THEN to_jsonb(d.bib_year) ELSE '""'::jsonb END END, 'bib_authors', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_authors') THEN to_jsonb(COALESCE(d.bib_authors, '')) END, 'bib_venue', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_venue') THEN to_jsonb(COALESCE(d.bib_venue, '')) END, 'bib_citation_count', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_citation_count') THEN CASE WHEN (d.bib_enriched_at IS NOT NULL OR COALESCE(d.bib_year, 0) <> 0 OR COALESCE(d.bib_citation_count, 0) <> 0 OR COALESCE(d.bib_authors, '') <> '' OR COALESCE(d.bib_venue, '') <> '' OR COALESCE(d.bib_semantic_scholar_id, '') <> '' OR COALESCE(d.bib_openalex_id, '') <> '' OR COALESCE(d.bib_doi, '') <> '') THEN to_jsonb(COALESCE(d.bib_citation_count, 0)) ELSE '""'::jsonb END END, 'indexed_at', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'indexed_at') THEN CASE WHEN d.indexed_at IS NOT NULL THEN to_jsonb(to_char(d.indexed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"')) ELSE COALESCE(NULLIF(c.metadata -> 'indexed_at', 'null'::jsonb), '""'::jsonb) END END, 'content_type_shown', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type_shown') THEN to_jsonb(CASE WHEN f.fmt IS NOT NULL THEN f.fmt WHEN d.content_type ~ '\S' THEN d.content_type ELSE COALESCE(c.metadata ->> 'content_type', '') END) END ) ELSE '{}'::jsonb END) AS eff ) e WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash AND d.deleted_at IS NULL AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) ) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
GRANT EXECUTE ON FUNCTION nexus.manifest_search_1024(nexus.vector,text,bytea[],text[],jsonb,text,jsonb,text,integer,text,text,boolean) TO nexus_svc;
DROP FUNCTION IF EXISTS nexus.text_gated_search_allowed_384(nexus.vector,text,bytea[],text[],jsonb,text,integer,text,text);
CREATE FUNCTION nexus.text_gated_search_allowed_384(p_query nexus.vector, p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
GRANT EXECUTE ON FUNCTION nexus.text_gated_search_allowed_384(nexus.vector,text,bytea[],text[],jsonb,text,integer,text,text,boolean) TO nexus_svc;
DROP FUNCTION IF EXISTS nexus.text_gated_search_allowed_768(nexus.vector,text,bytea[],text[],jsonb,text,integer,text,text);
CREATE FUNCTION nexus.text_gated_search_allowed_768(p_query nexus.vector, p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
