DROP FUNCTION IF EXISTS nexus.text_gated_search_allowed_1024(nexus.vector,text,bytea[],text[],jsonb,text,integer,text,text);
CREATE FUNCTION nexus.text_gated_search_allowed_1024(p_query nexus.vector, p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n integer, p_embedding_model text, p_tenant text, p_exclude_sensitive boolean DEFAULT false) RETURNS TABLE(id text, content text, collection text, distance double precision, metadata jsonb, retention text) LANGUAGE sql STABLE AS $function$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (NOT p_exclude_sensitive OR NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks sm JOIN nexus.catalog_documents sd ON sd.tenant_id = sm.tenant_id AND sd.tumbler = sm.doc_id WHERE sm.tenant_id = c.tenant_id AND sm.collection = c.collection AND sm.chash = c.chash AND sd.deleted_at IS NULL AND sd.sensitive)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $function$;
GRANT EXECUTE ON FUNCTION nexus.text_gated_search_allowed_1024(nexus.vector,text,bytea[],text[],jsonb,text,integer,text,text,boolean) TO nexus_svc;
