:jsonb) END END, 'source_author', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_author') THEN CASE WHEN COALESCE(d.author, '') ~ '\S' THEN to_jsonb(d.author) ELSE COALESCE(NULLIF(c.metadata -> 'source_author', 'null'::jsonb), '""'::jsonb) END END, 'bib_doi', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_doi') THEN to_jsonb(d.bib_doi) END, 'bib_openalex_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_openalex_id') THEN to_jsonb(d.bib_openalex_id) END, 'bib_semantic_scholar_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_semantic_scholar_id') THEN to_jsonb(d.bib_semantic_scholar_id) END, 'content_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type') THEN to_jsonb(array_remove(ARRAY[ CASE WHEN f.fmt IS NOT NULL THEN CASE WHEN f.fmt IN ('pdf', 'markdown') THEN f.fmt END ELSE CASE WHEN c.metadata ->> 'content_type' IN ('pdf', 'markdown') THEN c.metadata ->> 'content_type' END END, CASE WHEN d.content_type ~ '\S' THEN CASE WHEN d.content_type NOT IN ('pdf', 'markdown') THEN d.content_type END ELSE CASE WHEN COALESCE(c.metadata ->> 'content_type', CASE WHEN f.fmt IS NULL THEN '' END) NOT IN ('pdf', 'markdown') THEN COALESCE(c.metadata ->> 'content_type', CASE WHEN f.fmt IS NULL THEN '' END) END END ], NULL)) END, 'tags', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'tags') THEN CASE WHEN p_manifest_path IS NOT NULL AND position('"tags"' in p_manifest_path) > 0 THEN nexus.catalog_tag_set(CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'tags'), 'null') <> 'null' THEN d.metadata -> 'tags' ELSE c.metadata -> 'tags' END) ELSE '[""]'::jsonb END END, 'category', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'category') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'category'), 'null') <> 'null' THEN d.metadata -> 'category' ELSE COALESCE(NULLIF(c.metadata -> 'category', 'null'::jsonb), '""'::jsonb) END END, 'ttl_days', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'ttl_days') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'ttl_days'), 'null') <> 'null' THEN d.metadata -> 'ttl_days' ELSE COALESCE(NULLIF(c.metadata -> 'ttl_days', 'null'::jsonb), '""'::jsonb) END END, 'source_agent', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_agent') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'source_agent'), 'null') <> 'null' THEN d.metadata -> 'source_agent' ELSE COALESCE(NULLIF(c.metadata -> 'source_agent', 'null'::jsonb), '""'::jsonb) END END, 'extraction_method', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_method') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_method'), 'null') <> 'null' THEN d.metadata -> 'extraction_method' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_method', 'null'::jsonb), '""'::jsonb) END END, 'quality_gate_overridden', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'quality_gate_overridden') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'quality_gate_overridden'), 'null') <> 'null' THEN d.metadata -> 'quality_gate_overridden' ELSE COALESCE(NULLIF(c.metadata -> 'quality_gate_overridden', 'null'::jsonb), '""'::jsonb) END END, 'extraction_source', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_source') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_source'), 'null') <> 'null' THEN d.metadata -> 'extraction_source' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_source', 'null'::jsonb), '""'::jsonb) END END, 'frecency_score', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'frecency_score') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'frecency_score'), 'null') <> 'null' THEN d.metadata -> 'frecency_score' ELSE COALESCE(NULLIF(c.metadata -> 'frecency_score', 'null'::jsonb), '""'::jsonb) END END ) || CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_year') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_authors') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_venue') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_citation_count') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'indexed_at') OR nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type_shown') THEN jsonb_build_object( 'bib_year', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_year') THEN CASE WHEN COALESCE(d.bib_year, 0) <> 0 THEN to_jsonb(d.bib_year) ELSE '""'::jsonb END END, 'bib_authors', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_authors') THEN to_jsonb(COALESCE(d.bib_authors, '')) END, 'bib_venue', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_venue') THEN to_jsonb(COALESCE(d.bib_venue, '')) END, 'bib_citation_count', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_citation_count') THEN CASE WHEN (d.bib_enriched_at IS NOT NULL OR COALESCE(d.bib_year, 0) <> 0 OR COALESCE(d.bib_citation_count, 0) <> 0 OR COALESCE(d.bib_authors, '') <> '' OR COALESCE(d.bib_venue, '') <> '' OR COALESCE(d.bib_semantic_scholar_id, '') <> '' OR COALESCE(d.bib_openalex_id, '') <> '' OR COALESCE(d.bib_doi, '') <> '') THEN to_jsonb(COALESCE(d.bib_citation_count, 0)) ELSE '""'::jsonb END END, 'indexed_at', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'indexed_at') THEN CASE WHEN d.indexed_at IS NOT NULL THEN to_jsonb(to_char(d.indexed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"')) ELSE COALESCE(NULLIF(c.metadata -> 'indexed_at', 'null'::jsonb), '""'::jsonb) END END, 'content_type_shown', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type_shown') THEN to_jsonb(CASE WHEN f.fmt IS NOT NULL THEN f.fmt WHEN d.content_